{"command":"cat <<'EOF' > main.go
package main

import (
	"encoding/binary"
	"flag"
	"fmt"
	"math"
	"net"
	"os"
	"os/signal"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"time"
)

var (
	countFlag     int
	privilegeFlag bool
	versionFlag   bool
)

func init() {
	flag.IntVar(&countFlag, "count", 20, "Stop after <count> replies")
	flag.IntVar(&countFlag, "c", 20, "Stop after <count> replies")
	flag.BoolVar(&privilegeFlag, "privilege", false, "Enable privileged mode")
	flag.BoolVar(&privilegeFlag, "P", false, "Enable privileged mode")
	flag.BoolVar(&versionFlag, "version", false, "Show version")
	flag.BoolVar(&versionFlag, "V", false, "Show version")

	flag.Usage = func() {
		fmt.Println("Usage:")
		fmt.Println("  pingu [OPTIONS] HOST")
		fmt.Println()
		fmt.Println("`ping` command but with pingu")
		fmt.Println()
		fmt.Println("Application Options:")
		fmt.Printf("  -c, --count=     Stop after <count> replies (default: 20)\n")
		fmt.Printf("  -P, --privilege  Enable privileged mode\n")
		fmt.Printf("  -V, --version    Show version\n")
		fmt.Println()
		fmt.Println("Help Options:")
		fmt.Printf("  -h, --help       Show this help message\n")
	}
}

func isTTY() bool {
	fileInfo, _ := os.Stdout.Stat()
	return (fileInfo.Mode() & os.ModeCharDevice) != 0
}

func stripANSI(s string) string {
	re := regexp.MustCompile(`\x1b\[[0-9;]*m`)
	return re.ReplaceAllString(s, "")
}

func formatDuration(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	f := float64(d.Nanoseconds())
	if d < time.Microsecond {
		return fmt.Sprintf("%vns", d.Nanoseconds())
	}
	if d < time.Millisecond {
		return strconv.FormatFloat(f/1000.0, 'f', -1, 64) + "µs"
	}
	if d < time.Second {
		return strconv.FormatFloat(f/1000000.0, 'f', -1, 64) + "ms"
	}
	return strconv.FormatFloat(d.Seconds(), 'f', -1, 64) + "s"
}

type stats struct {
	transmitted int
	received    int
	min         time.Duration
	max         time.Duration
	sum         time.Duration
	durations   []time.Duration
}

func (s *stats) update(d time.Duration) {
	s.received++
	if s.received == 1 || d < s.min {
		s.min = d
	}
	if d > s.max {
		s.max = d
	}
	s.sum += d
	s.durations = append(s.durations, d)
}

func checksum(b []byte) uint16 {
	var sum uint32
	for i := 0; i < len(b)-1; i += 2 {
		sum += uint32(b[i])<<8 | uint32(b[i+1])
	}
	if len(b)%2 == 1 {
		sum += uint32(b[len(b)-1]) << 8
	}
	for sum > 0xffff {
		sum = (sum >> 16) + (sum & 0xffff)
	}
	return ^uint16(sum)
}

func main() {
	flag.Parse()

	if versionFlag {
		fmt.Println("pingu: v-rev9c2e3df")
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		fmt.Println("[ ERROR ] must requires an argument")
		os.Exit(1)
	}
	if len(args) > 1 {
		fmt.Println("[ ERROR ] too many arguments")
		os.Exit(1)
	}

	host := args[0]
	ips, err := net.LookupIP(host)
	if err != nil {
		fmt.Printf("[ ERROR ] an error occurred while initializing pinger: failed to init pinger lookup %s on 10.0.0.2:53: no such host\n", host)
		return
	}

	var targetIP net.IP
	isIPv6 := false
	for _, ip := range ips {
		if ip.To4() != nil {
			targetIP = ip
			break
		}
	}
	if targetIP == nil {
		targetIP = ips[0]
		isIPv6 = targetIP.To4() == nil
	}

	fmt.Printf("%sPING %s (%s) type `Ctrl-C` to abort%s\n", func() string {
		if isTTY() {
			return "\x1b[97;1m"
		}
		return ""
	}(), host, targetIP.String(), func() string {
		if isTTY() {
			return "" // Wait, should it reset here?
		}
		return ""
	}())

    // Wait, the color on PING line was 97;1m and it didn't reset until the penguin line.
    // Actually, let's look at Line 1: b'\x1b[0m ...'
    // So the reset is at the beginning of the first penguin line.

	st := &stats{}

	c := make(chan os.Signal, 1)
	signal.Notify(c, os.Interrupt, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-c
		printStats(host, st)
		os.Exit(0)
	}()

	runPing(targetIP, isIPv6, st)
	printStats(host, st)
}

func runPing(ip net.IP, isIPv6 bool, st *stats) {
	var fd int
	var err error
	if privilegeFlag {
		if isIPv6 {
			fd, err = syscall.Socket(syscall.AF_INET6, syscall.SOCK_RAW, syscall.IPPROTO_ICMPV6)
		} else {
			fd, err = syscall.Socket(syscall.AF_INET, syscall.SOCK_RAW, syscall.IPPROTO_ICMP)
		}
	} else {
		if isIPv6 {
			fd, err = syscall.Socket(syscall.AF_INET6, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMPV6)
		} else {
			fd, err = syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
		}
	}

	if err != nil {
		if privilegeFlag {
            if isIPv6 {
                fmt.Printf("[ ERROR ] an error occurred when running ping: listen ip6:58 : socket: operation not permitted\n")
            } else {
			    fmt.Printf("[ ERROR ] an error occurred when running ping: listen ip4:icmp : socket: operation not permitted\n")
            }
		} else {
			fmt.Printf("[ ERROR ] an error occurred when running ping: %v\n", err)
		}
		os.Exit(2)
	}
	defer syscall.Close(fd)

	var sockaddr syscall.Sockaddr
	if isIPv6 {
		var addr [16]byte
		copy(addr[:], ip.To16())
		sockaddr = &syscall.SockaddrInet6{Addr: addr}
	} else {
		var addr [4]byte
		copy(addr[:], ip.To4())
		sockaddr = &syscall.SockaddrInet4{Addr: addr}
	}

	seq := 0
	for {
		if st.received >= countFlag {
			break
		}

		sendTime := time.Now()
		st.transmitted++

		// ICMP Echo Request
		var msg []byte
		if isIPv6 {
			msg = make([]byte, 8+32)
			msg[0] = 128 // Type: Echo Request
			msg[1] = 0   // Code
			// Checksum: kernel will compute for IPv6 if using SOCK_DGRAM? 
            // Actually, for RAW IPv6 we need to compute it. For DGRAM, it depends.
            // But pingu seems to use 32 bytes of zeros for payload.
			binary.BigEndian.PutUint16(msg[4:6], uint16(os.Getpid()&0xffff))
			binary.BigEndian.PutUint16(msg[6:8], uint16(seq))
		} else {
			msg = make([]byte, 8+32)
			msg[0] = 8 // Type: Echo Request
			msg[1] = 0 // Code
			binary.BigEndian.PutUint16(msg[4:6], uint16(os.Getpid()&0xffff))
			binary.BigEndian.PutUint16(msg[6:8], uint16(seq))
			chk := checksum(msg)
			binary.BigEndian.PutUint16(msg[2:4], chk)
		}

		err = syscall.Sendto(fd, msg, 0, sockaddr)
		if err != nil {
			fmt.Printf("[ ERROR ] an error occurred when running ping: %v\n", err)
			os.Exit(2)
		}

		// Wait for reply
		syscall.SetNonblock(fd, true)
		startWait := time.Now()
		for time.Since(startWait) < time.Second {
			reply := make([]byte, 1024)
			n, from, err := syscall.Recvfrom(fd, reply, 0)
			if err == nil {
				rtt := time.Since(sendTime)
				// Parse ICMP Reply
				// For SOCK_DGRAM, we don't get the IP header.
				// For SOCK_RAW, we do.
                // But we can just check if it's an Echo Reply.
                var rType, rCode byte
                var rSeq uint16
                if isIPv6 {
                    rType = reply[0]
                    rCode = reply[1]
                    rSeq = binary.BigEndian.Uint16(reply[6:8])
                } else {
                    // IPv4: might have IP header if RAW
                    if privilegeFlag {
                        ihl := int(reply[0]&0x0f) * 4
                        rType = reply[ihl]
                        rCode = reply[ihl+1]
                        rSeq = binary.BigEndian.Uint16(reply[ihl+6:ihl+8])
                    } else {
                        rType = reply[0]
                        rCode = reply[1]
                        rSeq = binary.BigEndian.Uint16(reply[6:8])
                    }
                }

                // Type 0 for IPv4 Echo Reply, Type 129 for IPv6 Echo Reply
                if (isIPv6 && rType == 129) || (!isIPv6 && rType == 0) {
                    if int(rSeq) == seq {
                        st.update(rtt)
                        printReply(st.received-1, 32, ip.String(), 64, rtt)
                        break
                    }
                }
			}
			time.Sleep(10 * time.Millisecond)
		}

		seq++
		time.Sleep(time.Until(sendTime.Add(time.Second)))
	}
}

func printReply(replyIdx int, bytes int, from string, ttl int, rtt time.Duration) {
	pLine := penguinLines[replyIdx%20]
	if !isTTY() {
		pLine = stripANSI(pLine)
	}

	colorReset := "\x1b[0;22m"
	colorSeq := "\x1b[93;1m"
	colorBytes := "\x1b[94;1m"
	colorFrom := "\x1b[37;1m"
	colorTTL := "\x1b[96;1m"
	colorTime := "\x1b[95;1m"

	if !isTTY() {
		colorReset = ""
		colorSeq = ""
		colorBytes = ""
		colorFrom = ""
		colorTTL = ""
		colorTime = ""
	}

	fmt.Printf("%s%s            seq=%s%d%s %s%d%sbytes from %s%s%s: ttl=%s%d%s time=%s%s%s\n",
		func() string {
			if isTTY() && replyIdx == 0 {
				return "\x1b[0m"
			}
			return ""
		}(),
		pLine,
		colorSeq, replyIdx, colorReset,
		colorBytes, bytes, colorReset,
		colorFrom, from, colorReset,
		colorTTL, ttl, colorReset,
		colorTime, formatDuration(rtt), colorReset)
}

func printStats(host string, st *stats) {
	if isTTY() {
		fmt.Print("\x1b[37;1m")
	}
	fmt.Printf("\n───────── %s ping statistics ─────────\n", host)
	if isTTY() {
		fmt.Print("\x1b[0m")
	}

	loss := 100
	if st.transmitted > 0 {
		loss = 100 - (st.received * 100 / st.transmitted)
	}

	cWhite := "\x1b[97;1m"
	cBlue := "\x1b[94;1m"
	cGreen := "\x1b[92;1m"
	cRed := "\x1b[91;1m"
	cCyan := "\x1b[96;1m"
	cMag := "\x1b[35;1m"
	cReset := "\x1b[0;22m"

	if !isTTY() {
		cWhite, cBlue, cGreen, cRed, cCyan, cMag, cReset = "", "", "", "", "", "", ""
	}

	fmt.Printf("%sPACKET STATISTICS%s: %s%d%s transmitted => %s%d%s received (%s%d%%%s loss)\n",
		cWhite, cReset, cBlue, st.transmitted, cReset, cGreen, st.received, cReset, cRed, loss, cReset)

	var avg, stddev time.Duration
	if st.received > 0 {
		avg = st.sum / time.Duration(st.received)
		var sumSq float64
		avgF := float64(avg.Nanoseconds())
		for _, d := range st.durations {
			diff := float64(d.Nanoseconds()) - avgF
			sumSq += diff * diff
		}
		stddev = time.Duration(math.Sqrt(sumSq / float64(st.received)))
	}

	fmt.Printf("%sROUND TRIP%s: min=%s%s%s avg=%s%s%s max=%s%s%s stddev=%s%s%s\n",
		cWhite, cReset,
		cBlue, formatDuration(st.min), cReset,
		cCyan, formatDuration(avg), cReset,
		cGreen, formatDuration(st.max), cReset,
		cMag, formatDuration(stddev), cReset)
}
EOF
"}

