func runPing(ip net.IP, isIPv6 bool, st *stats) {
	var fd int
	var err error
	if privilegeFlag {
		if isIPv6 {
			fd, err = syscall.Socket(syscall.AF_INET6, syscall.SOCK_RAW, syscall.IPPROTO_ICMPV6)
		} else {
			fd, err = syscall.Socket(syscall.AF_INET, syscall.SOCK_RAW, syscall.IPPROTO_ICMP)
		}
	} else {
		if isIPv6 {
			fd, err = syscall.Socket(syscall.AF_INET6, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMPV6)
		} else {
			fd, err = syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
		}
	}

	if err != nil {
		if privilegeFlag {
			if isIPv6 {
				fmt.Printf("[ ERROR ] an error occurred when running ping: listen ip6:58 : socket: operation not permitted\n")
			} else {
				fmt.Printf("[ ERROR ] an error occurred when running ping: listen ip4:icmp : socket: operation not permitted\n")
			}
		} else {
			fmt.Printf("[ ERROR ] an error occurred when running ping: %v\n", err)
		}
		os.Exit(2)
	}
	defer syscall.Close(fd)

	var sockaddr syscall.Sockaddr
	if isIPv6 {
		var addr [16]byte
		copy(addr[:], ip.To16())
		sockaddr = &syscall.SockaddrInet6{Addr: addr}
	} else {
		var addr [4]byte
		copy(addr[:], ip.To4())
		sockaddr = &syscall.SockaddrInet4{Addr: addr}
	}

	seq := 0
	for {
		if st.received >= countFlag {
			break
		}

		sendTime := time.Now()
		st.transmitted++

		var msg []byte
		if isIPv6 {
			msg = make([]byte, 8+32)
			msg[0] = 128
			msg[1] = 0
			binary.BigEndian.PutUint16(msg[4:6], uint16(os.Getpid()&0xffff))
			binary.BigEndian.PutUint16(msg[6:8], uint16(seq))
            // For IPv6, we usually don't need to compute the checksum in SOCK_DGRAM
            // But if it's RAW, we do. However, privilege mode is rare.
		} else {
			msg = make([]byte, 8+32)
			msg[0] = 8
			msg[1] = 0
			binary.BigEndian.PutUint16(msg[4:6], uint16(os.Getpid()&0xffff))
			binary.BigEndian.PutUint16(msg[6:8], uint16(seq))
			chk := checksum(msg)
			binary.BigEndian.PutUint16(msg[2:4], chk)
		}

		err = syscall.Sendto(fd, msg, 0, sockaddr)
		if err != nil {
			fmt.Printf("[ ERROR ] an error occurred when running ping: %v\n", err)
			os.Exit(2)
		}

		syscall.SetNonblock(fd, false)
		tv := syscall.Timeval{Sec: 1, Usec: 0}
		syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

		reply := make([]byte, 1024)
		n, _, err := syscall.Recvfrom(fd, reply, 0)
		if err == nil {
			rtt := time.Since(sendTime)
			var rType byte
			var rSeq uint16
			if isIPv6 {
				rType = reply[0]
				rSeq = binary.BigEndian.Uint16(reply[6:8])
			} else {
				ihl := 0
				if privilegeFlag {
					ihl = int(reply[0]&0x0f) * 4
				}
				rType = reply[ihl]
				rSeq = binary.BigEndian.Uint16(reply[ihl+6:ihl+8])
			}

			if (isIPv6 && rType == 129) || (!isIPv6 && rType == 0) {
				if int(rSeq) == seq {
					st.update(rtt)
					printReply(st.received-1, 32, ip.String(), 64, rtt)
				}
			}
		}

		seq++
		time.Sleep(time.Until(sendTime.Add(time.Second)))
	}
}

func printReply(replyIdx int, bytes int, from string, ttl int, rtt time.Duration) {
	pLine := penguinLines[replyIdx%20]
	if !isTTY() {
		pLine = stripANSI(pLine)
	}

	cReset := "\x1b[0;22m"
	cSeq := "\x1b[93;1m"
	cBytes := "\x1b[94;1m"
	cFrom := "\x1b[37;1m"
	cTTL := "\x1b[96;1m"
	cTime := "\x1b[95;1m"

	if !isTTY() {
		cReset, cSeq, cBytes, cFrom, cTTL, cTime = "", "", "", "", "", ""
	}

