func isTTY() bool {
	fileInfo, _ := os.Stdout.Stat()
	return (fileInfo.Mode() & os.ModeCharDevice) != 0
}

func stripANSI(s string) string {
	re := regexp.MustCompile(`\x1b\[[0-9;]*m`)
	return re.ReplaceAllString(s, "")
}

func formatDuration(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	f := float64(d.Nanoseconds())
	if d < time.Microsecond {
		return fmt.Sprintf("%vns", d.Nanoseconds())
	}
	if d < time.Millisecond {
		return strconv.FormatFloat(f/1000.0, 'f', -1, 64) + "µs"
	}
	if d < time.Second {
		return strconv.FormatFloat(f/1000000.0, 'f', -1, 64) + "ms"
	}
	return strconv.FormatFloat(d.Seconds(), 'f', -1, 64) + "s"
}

type stats struct {
	transmitted int
	received    int
	min         time.Duration
	max         time.Duration
	sum         time.Duration
	durations   []time.Duration
}

func (s *stats) update(d time.Duration) {
	s.received++
	if s.received == 1 || d < s.min {
		s.min = d
	}
	if d > s.max {
		s.max = d
	}
	s.sum += d
	s.durations = append(s.durations, d)
}

func checksum(b []byte) uint16 {
	var sum uint32
	for i := 0; i < len(b)-1; i += 2 {
		sum += uint32(b[i])<<8 | uint32(b[i+1])
	}
	if len(b)%2 == 1 {
		sum += uint32(b[len(b)-1]) << 8
	}
	for sum > 0xffff {
		sum = (sum >> 16) + (sum & 0xffff)
	}
	return ^uint16(sum)
}

