		if privilegeFlag {
			if isIPv6 {
				fmt.Printf("[ ERROR ] an error occurred when running ping: listen ip6:58 : socket: operation not permitted\n")
			} else {
				fmt.Printf("[ ERROR ] an error occurred when running ping: listen ip4:icmp : socket: operation not permitted\n")
			}
		} else {
			fmt.Printf("[ ERROR ] an error occurred when running ping: %v\n", err)
		}
		os.Exit(2)
