	if isIPv6 {
		var addr [16]byte
		copy(addr[:], ip.To16())
		sockaddr = &syscall.SockaddrInet6{Addr: addr}
	} else {
		var addr [4]byte
		copy(addr[:], ip.To4())
		sockaddr = &syscall.SockaddrInet4{Addr: addr}
	}

