		if err == nil {
			rtt := time.Since(sendTime)
			var rType byte
			var rSeq uint16
			if isIPv6 {
				if n >= 8 {
					rType = reply[0]
					rSeq = binary.BigEndian.Uint16(reply[6:8])
				}
			} else {
				ihl := 0
				if privilegeFlag {
					ihl = int(reply[0]&0x0f) * 4
				}
				if n >= ihl+8 {
					rType = reply[ihl]
					rSeq = binary.BigEndian.Uint16(reply[ihl+6:ihl+8])
				}
			}

			if (isIPv6 && rType == 129) || (!isIPv6 && rType == 0) {
				if int(rSeq) == seq {
					st.update(rtt)
					printReply(st.received-1, 32, ip.String(), 64, rtt)
				}
			}
		}

		seq++
		time.Sleep(time.Until(sendTime.Add(time.Second)))
	}
}

func printReply(replyIdx int, bytes int, from string, ttl int, rtt time.Duration) {
	pLine := penguinLines[replyIdx%20]
