	}

	cReset := "\x1b[0;22m"
	cSeq := "\x1b[93;1m"
	cBytes := "\x1b[94;1m"
	cFrom := "\x1b[37;1m"
	cTTL := "\x1b[96;1m"
	cTime := "\x1b[95;1m"

	if !isTTY() {
		cReset, cSeq, cBytes, cFrom, cTTL, cTime = "", "", "", "", "", ""
	}

	prefix := ""
	if isTTY() && replyIdx == 0 {
		prefix = "\x1b[0m"
	}

	fmt.Printf("%s%sseq=%s%d%s %s%d%sbytes from %s%s%s: ttl=%s%d%s time=%s%s%s\n",
		prefix, pLine,
		cSeq, replyIdx, cReset,
		cBytes, bytes, cReset,
		cFrom, from, cReset,
		cTTL, ttl, cReset,
		cTime, formatDuration(rtt), cReset)
}

func printStats(host string, st *stats) {
	headerPrefix := ""
	headerSuffix := ""
	if isTTY() {
		headerPrefix = "\x1b[37;1m"
		headerSuffix = "\x1b[0m"
	}
	fmt.Printf("\n%s───────── %s ping statistics ─────────%s\n", headerPrefix, host, headerSuffix)

	loss := 100
	if st.transmitted > 0 {
		loss = 100 - (st.received * 100 / st.transmitted)
	}

	cWhite, cBlue, cGreen, cRed, cCyan, cMag, cReset := "\x1b[97;1m", "\x1b[94;1m", "\x1b[92;1m", "\x1b[91;1m", "\x1b[96;1m", "\x1b[35;1m", "\x1b[0;22m"
	if !isTTY() {
		cWhite, cBlue, cGreen, cRed, cCyan, cMag, cReset = "", "", "", "", "", "", ""
	}

	fmt.Printf("%sPACKET STATISTICS%s: %s%d%s transmitted => %s%d%s received (%s%d%%%s loss)\n",
		cWhite, cReset, cBlue, st.transmitted, cReset, cGreen, st.received, cReset, cRed, loss, cReset)

	var avg, stddev time.Duration
	if st.received > 0 {
		avg = st.sum / time.Duration(st.received)
		var sumSq float64
		avgF := float64(avg.Nanoseconds())
		for _, d := range st.durations {
			diff := float64(d.Nanoseconds()) - avgF
			sumSq += diff * diff
		}
		stddev = time.Duration(math.Sqrt(sumSq / float64(st.received)))
	}

	fmt.Printf("%sROUND TRIP%s: min=%s%s%s avg=%s%s%s max=%s%s%s stddev=%s%s%s\n",
		cWhite, cReset,
		cBlue, formatDuration(st.min), cReset,
		cCyan, formatDuration(avg), cReset,
		cGreen, formatDuration(st.max), cReset,
		cMag, formatDuration(stddev), cReset)
}
